@media(max-width:640px){.topbar{grid-template-columns:1fr auto;padding:10px}.top-actions{grid-column:1/-1;justify-self:start}.layout,.layout.collapsed{grid-template-columns:1fr}.rail{border:0;border-bottom:1px solid var(--line);padding:10px}.rail .rail-content,.rail .rail-foot{display:none}.rail:not(.collapsed) .rail-content{display:block}.rail.collapsed{display:block;padding:10px}.rail-title{justify-content:flex-start}.workspace{padding:18px 12px}.welcome{margin-top:20px}.welcome h1{font-size:24px}.contextbar{margin-bottom:18px}.task-heading h1{font-size:20px}.task-heading{flex-wrap:wrap}.field-grid{grid-template-columns:1fr}.metric-row strong{font-size:21px}.metric-row span{font-size:11px}.surface{padding:16px}.topbar .mode-switch button{padding:6px 12px}.footer{padding:10px}.saved-list .surface{display:block}.key-values{grid-template-columns:82px 1fr}.dialog-body{padding:16px}}

/* v0.2 reuses the accepted v0.1 visual system; only the task hierarchy changes. */
.journey{max-width:1180px;margin:0 auto 18px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;border-bottom:1px solid var(--line);padding:0 0 14px}.journey strong{font-size:13px}.journey .link{margin-left:auto}.discovery-layout{max-width:1180px;margin:auto;display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,.95fr);gap:22px;align-items:start}.discovery-layout .surface{margin:0}.discovery-messages{max-height:290px;overflow-y:auto;margin:18px 0 22px;padding-right:6px}.discovery-messages .chat-line{font-size:13px}.next-question{margin:20px 0 16px;padding-top:16px;border-top:1px solid var(--line)}.next-question h3{font-size:15px;line-height:1.7}.next-question p{margin-top:7px}.reply-suggestions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.reply-suggestions>span{width:100%}.reply-suggestions button{font-size:12px;background:var(--soft);text-align:left}.framework-list{margin:16px 0;display:grid;gap:0}.framework-list>div{padding:12px 0;border-bottom:1px solid var(--line)}.framework-list dt{font-size:12px;color:var(--muted);margin-bottom:7px;display:flex;align-items:center;justify-content:space-between;gap:6px}.framework-list dd{margin:0;font-size:13px;line-height:1.75}.source-tag{font-size:10px;background:var(--soft);color:var(--muted);padding:2px 6px;border-radius:4px;white-space:nowrap}.framework-change{border-left:2px solid var(--accent);padding:9px 12px;background:#fff8f3;font-size:12px;line-height:1.65}.framework-change>span{color:var(--accent-dark);font-size:11px}.framework-footer .actions{margin-top:8px}.framework-footer>p{margin-top:12px}.framework-summary{max-width:1180px;margin:0 auto 20px;padding:12px 16px;background:#f6f3ee;border:1px solid var(--line);border-radius:9px;display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap}.framework-summary strong{font-size:12px}.framework-summary p{font-size:12px;color:var(--muted);margin-top:4px}.data-needs{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:22px 0}.data-needs>div{border-left:2px solid var(--line);padding-left:14px}.data-needs p{font-size:12px;color:var(--muted);margin:8px 0 12px}.journey-list{padding-left:24px}.journey-list li{padding:10px 0;color:var(--muted)}.journey-list li.current{color:var(--accent-dark)}.journey-list p{font-size:12px;margin-top:5px}
@media(max-width:1100px){.discovery-layout{grid-template-columns:minmax(0,1fr) minmax(300px,.9fr);gap:16px}.discovery-layout .surface{padding:17px}}
@media(max-width:900px){.discovery-layout{grid-template-columns:1fr}.discovery-messages{max-height:250px}}
@media(max-width:640px){.data-needs{grid-template-columns:1fr}.framework-list dt{flex-wrap:wrap}}

/* Only required wrapping for the contract-delta controls; v0.2 tokens and layout preserved. */
.contract-review{max-width:1180px;margin:0 auto 18px}.contract-review summary{color:var(--accent-dark)}.contract-review select{max-width:100%}.section-head,.file-item,.example{flex-wrap:wrap}.breadcrumbs,.key-values dd{overflow-wrap:anywhere}
